INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(24545, 'plPL', 'Święte i splugawione', 'Wbrew własnemu osądowi powierzam ci to zadanie, $N, bo najpewniej skończy się ono twoją zgubą.$b$bJeśli zlekceważysz moją radę i się go podejmiesz, zapewnię ci wiedzę i środki, by doprowadzić je do końca.$b$bMusisz wrócić do Groty Ostrza Mrozu i odzyskać Pomstę Światłości, porzucony młot Arthasa. Przekuty z saronitem i wytrawiony kwaśną krwią plugastw Króla Lisza, stanie się podstawą naszego dzieła.', 'Umieść Pomstę Światłości, 25 sztuk pierwotnego saronitu, kwaśną krew Zgnilca i kwaśną krew Ropniaka w kuźni run najwyższego lorda Mograine\'a w Cytadeli Lodowej Korony.$B$BKwaśną krew Zgnilca i kwaśną krew Ropniaka można zdobyć tylko w Cytadeli Lodowej Korony na poziomie trudności dla 25 osób.', '', 'Wróć do kuźni run w Cytadeli Lodowej Korony.', '', '', '', '', 0),
(24547, 'plPL', 'Uczta dusz', 'Ostrze Cienia to jedna z najpotężniejszych broni, jakie może zdobyć $c.$b$bCzy twoja żądza mocy została zaspokojona, $N?$b$b<Czujesz na sobie przenikliwe spojrzenie Mograine\'a.>$b$bTak myślałem. Zatem ostatnie ostrzeżenie...$b$bRozpoczynasz najbardziej zdradliwy etap swojej misji. Okiełznaj ambicje, bo jeśli twoje zamiary są nieczyste, przepadnie twoje życie, a nawet twoja dusza.$b$bBroń, którą trzymasz, to tylko pusta skorupa, zaledwie cień tego, czym może się stać. Jej prawdziwą moc uwolni dopiero pożarcie tysiąca dusz.', 'Najwyższy lord Darion Mograine chce, żebyś $gzabił:zabiła; Ostrzem Cienia 1000 sług Króla Lisza w Cytadeli Lodowej Korony. Dusze można zdobywać na poziomie trudności dla 10 lub 25 osób.', '', 'Wróć do najwyższego lorda Dariona Mograine\'a w Cytadeli Lodowej Korony.', 'Dusze pożarte przez Ostrze Cienia', '', '', '', 0),
(24548, 'plPL', 'Strzaskany tron', 'Tron Króla Lisza był niegdyś jego więzieniem. Sam Kil\'jaeden stworzył to naczynie z lodowych kryształów w kłębiącej się Otchłani wyłącznie po to, by uwięzić mściwego ducha Ner\'zhula.$b$bGdy Arthas uderzył w kryształ Ostrzem Mrozu, uwolnił duszę Ner\'zhula i pozwolił jej stopić się z własną. Odpryski z tego uderzenia są teraz rozsiane po całej cytadeli.$b$bBędę potrzebował tych odłamków, które mają tylko najpotężniejsi słudzy Króla Lisza, by zapieczętować moc twojego ostrza.', 'Najwyższy lord Darion Mograine chce, żebyś $gzebrał:zebrała; 50 odłamków cienistego mrozu.$B$BOdłamki cienistego mrozu można zdobyć tylko na poziomie trudności dla 25 osób.', '', 'Wróć do najwyższego lorda Dariona Mograine\'a.', '', '', '', '', 0),
(24549, 'plPL', 'Cieniożal...', '', 'Najwyższy lord Darion Mograine chce, żebyś $gprzyniósł:przyniosła; mu Ostrze Cienia.', '', '', '', '', '', '', 0),
(24743, 'plPL', 'Ostrze Cienia', '', '', '', '', '', '', '', '', 0),
(24748, 'plPL', 'Ostatnia reduta Króla Lisza', 'Cieniożal – świeżo wykuta broń, a już przesiąknięta historią tego świata, odrodzona ku przeznaczeniu, któremu nic nie dorówna.$b$bWraz z tą bronią spoczywa na tobie poważna odpowiedzialność, a nadszedł czas, by się z niej wywiązać.$b$bWeź tę broń z mitów i legend i ruszaj na wroga. Pomścij niezliczonych bohaterów poległych w jego bezlitosnej kampanii. Daj ukojenie ich udręczonym duszom.$b$bZbierz się w sobie, $N, i poprowadź Cieniożal, by wypełnił cel, dla którego go stworzono.', 'Najwyższy lord Darion Mograine w Cytadeli Lodowej Korony chce, żebyś $gzabił:zabiła; Króla Lisza.', '', 'Wróć do najwyższego lorda Dariona Mograine\'a.', 'Król Lisz pokonany', '', '', '', 0),
(24749, 'plPL', 'Wlew bezbożności', 'Zanim twoja broń osiągnie pełnię możliwości, musi zostać obdarzona swoimi szczególnymi mocami. Pierwszą z nich jest bezbożność.$b$bMusisz odnaleźć i pokonać tego, którego zwą profesorem Przebrzydem, ale jego śmierć nie jest twoim jedynym celem. Musisz obrócić jego własne zasoby przeciwko niemu.$b$bZnajdź sposób, by wchłonąć jego zmutowany szlam. Użyj tej plugawej substancji, by nasycić broń mocą bezbożności. Dopiero gdy to zrobisz, wyjawię ci kolejne zadanie.', 'Najwyższy lord Darion Mograine chce, żebyś $gnasycił:nasyciła; Ostrze Cienia mocą bezbożności i $gzabił:zabiła; profesora Przebrzyda.$B$BTo zadanie można ukończyć tylko w Cytadeli Lodowej Korony na poziomie trudności dla 25 osób.', 'Nasyć Ostrze Cienia mocą bezbożności, a potem zabij Przebrzyda.', 'Wróć do najwyższego lorda Dariona Mograine\'a.', '', '', '', '', 0),
(24756, 'plPL', 'Wlew krwi', 'Twoja broń jest gotowa, by przyjąć moc krwi.$b$bMusisz stanąć do walki z królową Lana\'thel i poddać się jej Krwawemu lustru. Sprawi ono, że Ostrze Cienia napije się krwi najbliższej żywej istoty. Tą istotą będziesz ty, $N.$b$bGdy ostrze zostanie w ten sposób przebudzone, pozwól, by owładnął tobą Szaleńczy głód krwi królowej, nakarm ostrze trzykrotnie, by je nasycić, a potem zgotuj królowej haniebną śmierć.$b$bNiech jej krzyki przeszyją uszy Króla Lisza, gdy będzie czekał na swój los.', 'Najwyższy lord Darion Mograine chce, żebyś $gnasycił:nasyciła; Ostrze Cienia krwią i $gpokonał:pokonała; królową Lana\'thel.$B$BTo zadanie można ukończyć tylko w Cytadeli Lodowej Korony na poziomie trudności dla 25 osób.', 'Nasyć Ostrze Cienia krwią, a potem pokonaj Lana\'thel.', 'Wróć do najwyższego lorda Dariona Mograine\'a.', '', '', '', '', 0),
(24757, 'plPL', 'Wlew mrozu', 'Ostrze Cienia jest gotowe przyjąć ostatni wlew mocy.$b$bSindragosa, wierzchowiec samego wroga, musi paść. Ale zanim ją powalisz, musisz przetrwać cztery ataki jej mroźnego oddechu, nie zaznając śmierci.$b$bBez swojego smoka nic nie stanie między tobą a Królem Lisza.', 'Najwyższy lord Darion Mograine polecił ci zabić Sindragosę po tym, jak przyjmiesz 4 ataki jej oddechu, dzierżąc Ostrze Cienia.$B$BTo zadanie można ukończyć tylko w Cytadeli Lodowej Korony na poziomie trudności dla 25 osób.', 'Nasyć Ostrze Cienia mrozem, a potem zabij Sindragosę.', 'Wróć do najwyższego lorda Dariona Mograine\'a.', '', '', '', '', 0),
