(24847, 'plPL', 'Zmiana zdania', '', '', '', 'Wróć do Ormusa Pokutnika.', '', '', '', '', 0),
(24869, 'plPL', 'Deprogramowanie', 'Mieliśmy nadzieję umieścić naszego człowieka w Kulcie Potępionych, by od środka przyglądać się knowaniom Króla Lisza, ale... nie doceniliśmy siły perswazji Arthasa i jego mrocznej kapłanki, Morowej Pani.$B$BNasz człowiek, Darnavan, jest teraz jednym z nich.$B$BJeśli zamierzasz przebić się przez Oratorium przed nami, wypatruj Darnavana. Jeśli zdołasz sprowadzić go do nas żywego, spróbujemy odwrócić pranie mózgu, jakie zrobił mu Kult.', 'Pokonaj Morową Panią, dbając o to, by Darnavan przeżył.', '', 'Wróć do infiltratora Minchara.', 'Uratuj Darnavana', '', '', '', 0),
(24870, 'plPL', 'Zabezpieczenie wałów', 'Jakby to miejsce samo w sobie nie było dość szalone, walczymy tu na dwóch frontach: z jednej strony Plaga, a z drugiej te przeklęte psy z Przymierza!$B$BMamy tu przygotować bezpieczne lądowisko dla naszych okrętów, ale jakiś olbrzymi kolos po drugiej stronie wałów ciska gruzem we wszystko, co się zbliży, i trzyma nasze mniejsze statki na dystans.$B$BBędę szczery – to dla nas trochę za dużo, ale ty i twoi towarzysze wyglądacie na takich, co dadzą mu radę.', 'Zabij gnijącego mroźnego olbrzyma.', '', 'Wróć do porucznika Kor\'kronu.', '', '', '', '', 0),
(24871, 'plPL', 'Zabezpieczenie wałów', 'Jakby to miejsce samo w sobie nie było dość szalone, walczymy tu na dwóch frontach: z jednej strony Plaga, a z drugiej te przeklęte psy z Hordy!$B$BMamy tu przygotować bezpieczne lądowisko dla naszych okrętów, ale jakiś olbrzymi kolos po drugiej stronie wałów ciska gruzem we wszystko, co się zbliży, i trzyma nasze mniejsze statki na dystans.$B$BBędę szczery – to dla nas trochę za dużo, ale ty i twoi towarzysze wyglądacie na takich, co dadzą mu radę.', 'Zabij gnijącego mroźnego olbrzyma.', '', 'Wróć do porucznika z Niebołamacza.', '', '', '', '', 0),
(24873, 'plPL', 'Randka z próbką', 'Profesor Przebrzyd zaszył się w swoim plugawym laboratorium, gdzie eksperymentuje i udoskonala coraz bardziej zabójcze odmiany zarazy, które mają zostać użyte przeciwko nam. Gdybyśmy tylko zdobyli czyste próbki tych toksyn, nasi badacze mogliby przyrządzić antidotum, które ocaliłoby niezliczone istnienia.$B$BJest jednak haczyk – właściwa próbka wymaga zmieszania dwóch aktywnych szczepów w żywym nosicielu. Jeśli będziesz mieć... nieszczęście... stać się takim nosicielem, wróć tu natychmiast, żebyśmy mogli pobrać z ciebie materiał do badań.', 'Wróć do alchemiczki Adrianny, będąc $gzarażonym:zarażoną; pomarańczową i zieloną zarazą.', 'Wróć z dwoma szczepami zarazy.', 'Wróć do Adrianny w Cytadeli Lodowej Korony.', '', '', '', '', 0),
(24874, 'plPL', 'Przyspieszenie krwi', 'Te krwiopijce z Plagi – San\'layn, jak się nazywają – przyprawiają mnie o dreszcze. Jeden z naszych najlepszych ludzi miał ich na oku. Ale dziś rano stracił czujność i dał się pojmać. Właśnie przesłuchuje go sama królowa, a jego krzyki niosą się echem po Karmazynowej Sali. Proszę, uratuj go, zanim będzie za późno!', 'Uratuj infiltratora Minchara, zanim zostanie stracony.', '', 'Porozmawiaj z Mincharem.', 'Minchar uratowany', '', '', '', 0),
(24875, 'plPL', 'Deprogramowanie', 'Mieliśmy nadzieję umieścić naszego człowieka w Kulcie Potępionych, by od środka przyglądać się knowaniom Króla Lisza, ale... nie doceniliśmy siły perswazji Arthasa i jego mrocznej kapłanki, Morowej Pani.$B$BNasz człowiek, Darnavan, jest teraz jednym z nich.$B$BJeśli zamierzasz przebić się przez Oratorium przed nami, wypatruj Darnavana. Jeśli zdołasz sprowadzić go do nas żywego, spróbujemy odwrócić pranie mózgu, jakie zrobił mu Kult.', 'Pokonaj Morową Panią, dbając o to, by Darnavan przeżył.', '', 'Wróć do infiltratora Minchara.', 'Uratuj Darnavana', '', '', '', 0),
(24876, 'plPL', 'Zabezpieczenie wałów', 'Jakby to miejsce samo w sobie nie było dość szalone, walczymy tu na dwóch frontach: z jednej strony Plaga, a z drugiej te przeklęte psy z Hordy!$B$BMamy tu przygotować bezpieczne lądowisko dla naszych okrętów, ale jakiś olbrzymi kolos po drugiej stronie wałów ciska gruzem we wszystko, co się zbliży, i trzyma nasze mniejsze statki na dystans.$B$BBędę szczery – to dla nas trochę za dużo, ale ty i twoi towarzysze wyglądacie na takich, co dadzą mu radę.', 'Zabij gnijącego mroźnego olbrzyma.', '', 'Wróć do porucznika z Niebołamacza.', '', '', '', '', 0),
(24877, 'plPL', 'Zabezpieczenie wałów', 'Jakby to miejsce samo w sobie nie było dość szalone, walczymy tu na dwóch frontach: z jednej strony Plaga, a z drugiej te przeklęte psy z Przymierza!$B$BMamy tu przygotować bezpieczne lądowisko dla naszych okrętów, ale jakiś olbrzymi kolos po drugiej stronie wałów ciska gruzem we wszystko, co się zbliży, i trzyma nasze mniejsze statki na dystans.$B$BBędę szczery – to dla nas trochę za dużo, ale ty i twoi towarzysze wyglądacie na takich, co dadzą mu radę.', 'Zabij gnijącego mroźnego olbrzyma.', '', 'Wróć do porucznika Kor\'kronu.', '', '', '', '', 0),
(24878, 'plPL', 'Randka z próbką', 'Profesor Przebrzyd zaszył się w swoim plugawym laboratorium, gdzie eksperymentuje i udoskonala coraz bardziej zabójcze odmiany zarazy, które mają zostać użyte przeciwko nam. Gdybyśmy tylko zdobyli czyste próbki tych toksyn, nasi badacze mogliby przyrządzić antidotum, które ocaliłoby niezliczone istnienia.$B$BJeśli natkniesz się na żywe okazy, wróć tu natychmiast, żebyśmy mogli pobrać od nich materiał do badań.', 'Wróć do alchemiczki Adrianny, będąc $gzarażonym:zarażoną; pomarańczową i zieloną zarazą.', 'Wróć z dwoma szczepami zarazy.', 'Wróć do Adrianny w Cytadeli Lodowej Korony.', '', '', '', '', 0),
(24879, 'plPL', 'Przyspieszenie krwi', 'Te krwiopijce z Plagi – San\'layn, jak się nazywają – przyprawiają mnie o dreszcze. Jeden z naszych najlepszych ludzi miał ich na oku. Ale dziś rano stracił czujność i dał się pojmać. Właśnie przesłuchuje go sama królowa, a jego krzyki niosą się echem po Karmazynowej Sali. Proszę, uratuj go, zanim będzie za późno!', 'Uratuj infiltratora Minchara, zanim zostanie stracony.', '', 'Porozmawiaj z Mincharem.', 'Minchar uratowany', '', '', '', 0),
(24912, 'plPL', 'Wzmocnienie', '', '', '', '', '', '', '', '', 0),
(24914, 'plPL', 'Własność prywatna', 'Nie dostrzegasz w tej skrzyni żadnych zawiasów ani otworów. Gdyby nie przesuwające się w środku przedmioty, łatwo byłoby wziąć ją za bryłę litego metalu.$b$bJeśli ktokolwiek zna sposób, by ją otworzyć, to najwyższy lord Mograine.', 'Zanieś zapieczętowaną skrzynię najwyższemu lordowi Darionowi Mograine\'owi w Cytadeli Lodowej Korony.', '', '', '', '', '', '', 0),
(24915, 'plPL', 'Ponowne spotkanie Mograine\'a', '', '', '', '', '', '', '', '', 0),
(25239, 'plPL', 'Ścieżka potęgi', '', '', '', 'Wróć do Ormusa Pokutnika.', '', '', '', '', 0),
