INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(24545, 'plPL', 'Gdy płomień pożera przedmioty, ogarnia cię głębokie poczucie grozy.', 0),
(24547, 'plPL', '<Najwyższy lord Mograine przez chwilę przygląda ci się w milczeniu.>$b$bZdaje się, że ten etap próby $gzniosłeś:zniosłaś; godnie podziwu, $N.$b$bMódl się, by los nadal ci sprzyjał...', 0),
(24548, 'plPL', 'To powinno wystarczyć, $N.$b$bPrzyjdź do mnie, gdy Ostrze Cienia zostanie w pełni wzmocnione, a spróbuję je ukończyć.', 0),
(24549, 'plPL', 'Gratulacje, $N.$b$bWbrew przytłaczającym przeciwnościom $gprzetrwałeś:przetrwałaś; burzę.$b$bUfam, że nagroda okaże się współmierna do twojej determinacji...', 0),
(24743, 'plPL', 'Słuchaj uważnie, $N. Przyjmując tę broń, przypieczętowujesz swój los.$B$BZwyciężysz albo ulegniesz.$B$BTo ja postawiłem cię na tej ścieżce. Dlatego odpowiadam za ciebie osobiście. Jeśli się zachwiejesz, moim obowiązkiem będzie uwolnić cię od tego życia.$B$BZapamiętaj moje słowa, $N, i nie zawiedź.', 0),
(24748, 'plPL', 'A więc w końcu się dokonało.$b$bNiech mieszkańcy Azeroth na zawsze pamiętają, czego tu dokonaliśmy. Niech ofiara tak wielu płonie w ich sercach po wieczność. Niech nigdy nie wahają się narażać życia w obliczu wielkiego zła.', 0),
(24749, 'plPL', 'Dobra robota, $N.$b$bUkończenie naszego dzieła jest blisko.', 0),
(24756, 'plPL', 'Dobra robota, $N.$b$bCieniożal jest niemal na wyciągnięcie ręki.', 0),
(24757, 'plPL', 'Topór napił się do syta, $N, a kuźnia jest niemal gotowa do stworzenia Cieniożala...', 0),
(24815, 'plPL', 'By odpokutować grzechy, których dopuściłem się jako jeden z rycerzy śmierci Króla Lisza, poświęciłem się tworzeniu pierścieni wielkiej mocy, by nasi bracia i siostry mogli ich używać w tej walce.$B$B$GDowiodłeś:Dowiodłaś;, że jesteś $gcennym sojusznikiem:cenną sojuszniczką; w walce z Plagą, $N. Jeśli twoje oddanie nie osłabnie, mogę ulepszać pierwotny projekt pierścienia.$B$BWybieraj ścieżkę rozważnie. Zmiana zdania będzie kosztować.', 0),
(24819, 'plPL', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24820, 'plPL', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24821, 'plPL', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
