(24823, 'plPL', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(24825, 'plPL', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(24826, 'plPL', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(24827, 'plPL', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(24828, 'plPL', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(24829, 'plPL', 'Jesteś $gprawdziwym orędownikiem:prawdziwą orędowniczką; naszej sprawy, $N. Nikt nie może twierdzić, że jest bardziej oddany tej walce niż ty.$B$BWróg wymawia twoje imię tylko szeptem, bo wie, że trzeba się z tobą liczyć.$B$BPrzyjmij ten skromny dar w nagrodę za twoje liczne triumfy.', 0),
(24830, 'plPL', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(24831, 'plPL', 'Jesteś $gprawdziwym orędownikiem:prawdziwą orędowniczką; naszej sprawy, $N. Nikt nie może twierdzić, że jest bardziej oddany tej walce niż ty.$B$BJesteś ostoją mądrości, a nasi sojusznicy mówią o tobie z najwyższą czcią. Wielu z nich zawdzięcza ci życie.$B$BPrzyjmij ten skromny dar w nagrodę za twoje liczne triumfy.', 0),
(24832, 'plPL', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(24833, 'plPL', 'Jesteś $gprawdziwym orędownikiem:prawdziwą orędowniczką; naszej sprawy, $N. Nikt nie może twierdzić, że jest bardziej oddany tej walce niż ty.$B$BPodobno sługi Plagi boją się ciebie bardziej niż samego Króla Lisza. Jesteś wcieloną pomstą.$B$BPrzyjmij ten skromny dar w nagrodę za twoje liczne triumfy.', 0),
(24834, 'plPL', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(24835, 'plPL', 'Jesteś $gprawdziwym orędownikiem:prawdziwą orędowniczką; naszej sprawy, $N. Nikt nie może twierdzić, że jest bardziej oddany tej walce niż ty.$B$BJesteś natchnieniem dla naszych sojuszników, a twoje niezachwiane męstwo każe się zawahać nawet najbardziej doświadczonym generałom wroga.$B$BPrzyjmij ten skromny dar w nagrodę za twoje liczne triumfy.', 0),
(24836, 'plPL', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24837, 'plPL', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24838, 'plPL', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
