(24843, 'plPL', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24844, 'plPL', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24845, 'plPL', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24846, 'plPL', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24847, 'plPL', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24869, 'plPL', 'Dziękuję, $N!$B$BMam wobec ciebie dług wdzięczności za uratowanie przyjaciela, którego uważałem za straconego na zawsze w szponach Kultu. A Krucjata Argentu ma u ciebie dług za bezcenne informacje, które Darnavan przynosi z czasów, gdy przemierzał korytarze tej cytadeli jako jeden z kultystów.$B$BProszę, przyjmij to w dowód wdzięczności. Niech Światłość doda ci sił, gdy będziesz torować sobie drogę przez to straszne miejsce.', 0),
(24870, 'plPL', 'Olbrzym nie żyje? Za Hordę!$B$BDroga naprzód i w górę stoi otworem. Weź trochę tych łupów wojennych w dowód naszej wdzięczności, a gdy Mroźny Tron zostanie starty w pył, wypijemy razem za zwycięstwo!', 0),
(24873, 'plPL', 'Nareszcie mamy żywe okazy do badań! $GPomogłeś:Pomogłaś; dziś ocalić niezliczone istnienia, $N.$B$BProszę, przyjmij to w podziękowaniu za ten wielki czyn.', 0),
(24874, 'plPL', 'Uff, myślałem, że już po mnie! Słyszałem, że w tych salach odprawiany jest jakiś rytuał wskrzeszenia, i poszedłem przyjrzeć się z bliska, ale jeden z tych przeklętych wampirów mnie wywęszył. Powiesili mnie tutaj i wysysali ze mnie energię życiową w nadziei, że się złamię i wyjawię nasze plany ataku. Jakbym w ogóle wiedział, co planuje Tirion!$b$bProszę, przyjmij te łupy wojenne jako drobny dowód wdzięczności za uratowanie mi życia.', 0),
(24875, 'plPL', 'Dziękuję, $N!$B$BMam wobec ciebie dług wdzięczności za uratowanie przyjaciela, którego uważałem za straconego na zawsze w szponach Kultu. A Krucjata Argentu ma u ciebie dług za bezcenne informacje, które Darnavan przynosi z czasów, gdy przemierzał korytarze tej cytadeli jako jeden z kultystów.$B$BProszę, przyjmij to w dowód wdzięczności. Niech Światłość doda ci sił, gdy będziesz torować sobie drogę przez to straszne miejsce.', 0),
(24877, 'plPL', 'Olbrzym nie żyje? Za Hordę!$B$BDroga naprzód i w górę stoi otworem. Weź trochę tych łupów wojennych w dowód naszej wdzięczności, a gdy Mroźny Tron zostanie starty w pył, wypijemy razem za zwycięstwo!', 0),
(24878, 'plPL', 'Nareszcie mamy żywe okazy do badań! $GPomogłeś:Pomogłaś; dziś ocalić niezliczone istnienia, $N.$B$BProszę, przyjmij to w podziękowaniu za ten wielki czyn.', 0),
(24879, 'plPL', 'Uff, myślałem, że już po mnie! Słyszałem, że w tych salach odprawiany jest jakiś rytuał wskrzeszenia, i poszedłem przyjrzeć się z bliska, ale jeden z tych przeklętych wampirów mnie wywęszył. Powiesili mnie tutaj i wysysali ze mnie energię życiową w nadziei, że się złamię i wyjawię nasze plany ataku. Jakbym w ogóle wiedział, co planuje Tirion!$b$bProszę, przyjmij te łupy wojenne jako drobny dowód wdzięczności za uratowanie mi życia.', 0),
(24912, 'plPL', 'Odsuń się, $N, i przygotuj się.', 0),
(24914, 'plPL', '<Gdy Mograine kreśli na każdej ścianie skrzyni złożony wzór run, pojawia się zarys wieka, a po komnacie niesie się echem ciche kliknięcie.>$B$BProszę bardzo, $N.', 0),
(24915, 'plPL', 'Niemożliwe...$B$BOjcze, czy to ty?!$B$B$GOddałeś:Oddałaś; mi wielką przysługę, $gbohaterze:bohaterko;. Oddaję ci wodze mojego wiernego rumaka. Zrób z nim, co zechcesz, ale nie zapominaj o tych, którzy pomogli ci w tym wiekopomnym czynie.', 0),
(25239, 'plPL', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(25240, 'plPL', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(25242, 'plPL', 'Jesteś $gprawdziwym orędownikiem:prawdziwą orędowniczką; naszej sprawy, $N. Nikt nie może twierdzić, że jest bardziej oddany tej walce niż ty.$B$BPodobno sługi Plagi boją się ciebie bardziej niż samego Króla Lisza. Jesteś wcieloną potęgą.$B$BPrzyjmij ten skromny dar w nagrodę za twoje liczne triumfy.', 0),
(25246, 'plPL', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(25247, 'plPL', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
