INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(36626, 2, 0, 'plPL', '%s puszcza bąka.'),
(36626, 6, 0, 'plPL', '%s wymiotuje.'),
(36789, 4, 0, 'plPL', 'Wybaczcie mi to, co czynię! Nie... mogę... przestać... ZOSTAŁY TYLKO KOSZMARY!'),
(36789, 5, 0, 'plPL', 'Tragiczna strata...'),
(36789, 6, 0, 'plPL', 'NIEUDACZNICY!'),
(37129, 8, 0, 'plPL', 'Sama pomsta... nie wystarczyła!'),
(37187, 7, 0, 'plPL', 'Najwyższy nadrządca Zaurzykieł podchodzi do syna i klęka przy jego ciele.'),
(37187, 8, 0, 'plPL', 'No\'ku kil zil\'nok ha tar.'),
(37187, 9, 0, 'plPL', 'Najwyższy nadrządca Zaurzykieł podnosi ciało syna i rusza w stronę Variana'),
(37813, 3, 0, 'plPL', '%s unieruchamia Muradina i jego strażników.'),
(37970, 6, 0, 'plPL', '...dlaczego...?'),
(37973, 6, 0, 'plPL', '%s charczy i umiera.');
